<script setup>
import { ref, computed, watch, onMounted, onUnmounted, nextTick } from 'vue'
import { LayoutDashboard, Calculator, Layers3, Printer, Settings2, Plus, Trash2, ExternalLink, Download, Upload, Box, Zap, Clock3, TrendingUp, PoundSterling, ChevronRight, Info, Check, X, Sun, Moon, Monitor, ChevronLeft, Menu, Sparkles, HelpCircle, Package } from 'lucide-vue-next'

const initial = { settings:{currency:'GBP',siteTitle:'PrintQuote',siteSubtitle:'PRINT COST STUDIO',logo:'',accent:'#6478f5',background:'#f7f8fb',darkBackground:'#11141c',themeMode:'auto',energyRate:0.28,labourRate:12,defaultMargin:30,onboardingCompleted:false}, filaments:[], printers:[], quotes:[], products:[] }
function clone(x){return JSON.parse(JSON.stringify(x))}
const state=ref(clone(initial))
const ready=ref(false), syncStatus=ref('Connecting…'), syncError=ref(false)
const systemDark=ref(window.matchMedia('(prefers-color-scheme: dark)').matches)
const media=window.matchMedia('(prefers-color-scheme: dark)')
const mediaListener=e=>{systemDark.value=e.matches}
const isDark=computed(()=>state.value.settings.themeMode==='dark'||(state.value.settings.themeMode==='auto'&&systemDark.value))
const theme=computed(()=>({ '--accent':state.value.settings.accent||'#6478f5','--surface':isDark.value?(state.value.settings.darkBackground||'#101827'):(state.value.settings.background||'#f7f9ff'), }))
function cycleTheme(){const modes=['auto','light','dark'];state.value.settings.themeMode=modes[(modes.indexOf(state.value.settings.themeMode)+1)%3]}
const themeLabel=computed(()=>({auto:'Auto theme',light:'Light theme',dark:'Dark theme'})[state.value.settings.themeMode]||'Auto theme')
let timer=null, saving=false, dirty=false, generation=0
async function api(url,options={}){const res=await fetch(url,{...options,headers:{'Content-Type':'application/json',...options.headers}});if(!res.ok)throw Error(`Server returned ${res.status}`);return res.json()}
async function refresh(){try{const data=await api('/api/state');if(!Array.isArray(data.filaments)||!Array.isArray(data.printers))throw Error('Invalid database state');state.value={...clone(initial),...data,products:Array.isArray(data.products)?data.products:[],settings:{...initial.settings,...data.settings,onboardingCompleted:data.settings?.onboardingCompleted ?? true}};ready.value=true; if(!state.value.settings.onboardingCompleted) startTour();syncError.value=false;syncStatus.value='Database connected'}catch(e){syncError.value=true;syncStatus.value='Database unavailable';console.error(e)}}
async function flush(){if(!ready.value||saving)return;saving=true;while(dirty){dirty=false;const payload=JSON.stringify(state.value);syncStatus.value='Saving…';try{await api('/api/state',{method:'PUT',body:payload});syncStatus.value='Saved to database';syncError.value=false}catch(e){dirty=true;syncError.value=true;syncStatus.value='Save failed — retrying';console.error(e);break}}saving=false;if(dirty){clearTimeout(timer);timer=setTimeout(flush,3000)}}
watch(state,()=>{if(!ready.value)return;dirty=true;syncStatus.value='Unsaved changes';clearTimeout(timer);timer=setTimeout(flush,650)},{deep:true})
onMounted(()=>{media.addEventListener('change',mediaListener);window.addEventListener('resize',positionTour);window.addEventListener('scroll',positionTour,true);refresh()})
onUnmounted(()=>{media.removeEventListener('change',mediaListener);window.removeEventListener('resize',positionTour);window.removeEventListener('scroll',positionTour,true);clearTimeout(timer)})
const logoInput=ref(null)
function uploadLogo(e){const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('image/')){toast('Please select an image');return}if(f.size>1024*1024){toast('Logo must be smaller than 1 MB');return}const reader=new FileReader();reader.onload=()=>{state.value.settings.logo=String(reader.result);toast('Logo updated')};reader.readAsDataURL(f);e.target.value=''}

const page=ref('calculator'), mobileMenu=ref(false), sidebarCollapsed=ref(false), notification=ref('')
function toast(t){notification.value=t;setTimeout(()=>notification.value='',3000)}
const uid=()=>Math.random().toString(36).slice(2,10)
const money=v=>new Intl.NumberFormat('en-GB',{style:'currency',currency:state.value.settings.currency||'GBP'}).format(Number(v)||0)
const num=(v)=>Math.max(0,Number(v)||0)
const quote=ref({name:'',filamentId:'',printerId:'',grams:120,hours:4,minutes:30,quantity:1,margin:30,extraCost:0,setupOverride:false})
const filament=computed(()=>state.value.filaments.find(f=>f.id===quote.value.filamentId))
const printer=computed(()=>state.value.printers.find(p=>p.id===quote.value.printerId))
const calc=computed(()=>{const q=quote.value,p=printer.value;const qty=Math.max(1,Math.floor(Number(q.quantity)||1));const hours=num(q.hours)+num(q.minutes)/60;const material=num(q.grams)/1000*num(filament.value?.price)*qty;const energy=hours*num(p?.power)/1000*num(state.value.settings.energyRate)*qty;const labour=(num(p?.setupMinutes)+num(p?.postMinutes)*qty)/60*num(state.value.settings.labourRate);const overhead=hours*num(p?.overheadRate)*qty;const extras=num(q.extraCost)*qty;const cost=material+energy+labour+overhead+extras;const margin=Math.min(99.9,num(q.margin));const price=cost/(1-margin/100);const profit=price-cost;return {qty,hours,material,energy,labour,overhead,extras,cost,price,profit,margin,markup:cost?profit/cost*100:0,unit:price/qty}})
const editingFilament=ref(null),editingPrinter=ref(null)
function newFilament(){if(tourActive.value&&tourStep.value===1) nextTour();editingFilament.value={id:uid(),name:'',brand:'',material:'PLA',colour:'',price:20,url:''}}
function editFilament(f){editingFilament.value=clone(f)}
function saveFilament(){const f=editingFilament.value;if(!f.name.trim()){toast('Please enter a filament name');return}if(f.url && !/^https?:\/\//i.test(f.url)){toast('Purchase link must start with http:// or https://');return}f.price=num(f.price);const idx=state.value.filaments.findIndex(x=>x.id===f.id);if(idx<0)state.value.filaments.push(f);else state.value.filaments[idx]=f;if(!quote.value.filamentId)quote.value.filamentId=f.id;editingFilament.value=null;toast('Filament saved')}
function removeFilament(id){if(!confirm('Delete this filament?'))return;state.value.filaments=state.value.filaments.filter(f=>f.id!==id);if(quote.value.filamentId===id)quote.value.filamentId=state.value.filaments[0]?.id||''}
function newPrinter(){if(tourActive.value&&tourStep.value===3) nextTour();editingPrinter.value={id:uid(),name:'',technology:'FDM',power:100,setupMinutes:10,postMinutes:10,overheadRate:0.25}}
function editPrinter(p){editingPrinter.value=clone(p)}
function savePrinter(){const p=editingPrinter.value;if(!p.name.trim()){toast('Please enter a printer name');return}for(const k of ['power','setupMinutes','postMinutes','overheadRate'])p[k]=num(p[k]);const idx=state.value.printers.findIndex(x=>x.id===p.id);if(idx<0)state.value.printers.push(p);else state.value.printers[idx]=p;if(!quote.value.printerId)quote.value.printerId=p.id;editingPrinter.value=null;toast('Printer saved')}
function removePrinter(id){if(!confirm('Delete this printer profile?'))return;state.value.printers=state.value.printers.filter(p=>p.id!==id);if(quote.value.printerId===id)quote.value.printerId=state.value.printers[0]?.id||''}
function saveQuote(){if(!filament.value||!printer.value){toast('Add a filament and printer first');return}state.value.quotes.unshift({id:uid(),name:quote.value.name.trim()||'Untitled print',date:new Date().toISOString(),filament:filament.value.name,printer:printer.value.name,details:clone(quote.value),result:clone(calc.value)});toast('Quote saved to history')}
function loadQuote(q){quote.value={...quote.value,...clone(q.details)};page.value='calculator';toast('Quote loaded')}
const editingProduct=ref(null)
function newProduct(){editingProduct.value={id:uid(),name:'',description:'',customer:'',sku:'',status:'Active',filamentId:quote.value.filamentId||'',printerId:quote.value.printerId||'',grams:num(quote.value.grams),hours:num(quote.value.hours),minutes:num(quote.value.minutes),price:Number(calc.value.price.toFixed(2)),notes:''}}
function productFromQuote(q){const d=q.details||{};editingProduct.value={id:uid(),name:q.name||'',description:'',customer:'',sku:'',status:'Active',filamentId:d.filamentId||'',printerId:d.printerId||'',grams:num(d.grams),hours:num(d.hours),minutes:num(d.minutes),price:Number(q.result?.price||0),notes:''};page.value='products'}
function saveProduct(){const item=editingProduct.value;if(!item.name.trim()){toast('Enter a product name');return}item.grams=num(item.grams);item.hours=num(item.hours);item.minutes=num(item.minutes);item.price=num(item.price);const i=state.value.products.findIndex(p=>p.id===item.id);if(i<0)state.value.products.unshift(clone(item));else state.value.products[i]=clone(item);editingProduct.value=null;toast('Product saved')}
function removeProduct(id){if(!confirm('Delete this saved product?'))return;state.value.products=state.value.products.filter(p=>p.id!==id)}
function loadProduct(p){quote.value={...quote.value,name:p.name,filamentId:p.filamentId,printerId:p.printerId,grams:p.grams,hours:p.hours,minutes:p.minutes};page.value='calculator';toast('Product loaded into calculator')}
function removeQuote(id){state.value.quotes=state.value.quotes.filter(q=>q.id!==id)}
function exportData(){const blob=new Blob([JSON.stringify(state.value,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='printquote-backup.json';a.click();URL.revokeObjectURL(url);toast('Backup downloaded')}
const fileInput=ref(null)
async function importData(e){const f=e.target.files?.[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!Array.isArray(data.filaments)||!Array.isArray(data.printers)||!data.settings)throw Error('Invalid backup');if(!confirm('Replace your current data with this backup?'))return;state.value={...clone(initial),...data};quote.value.filamentId=state.value.filaments[0]?.id||'';quote.value.printerId=state.value.printers[0]?.id||'';toast('Backup restored')}catch{toast('Could not read backup file')}finally{e.target.value=''}}
const nav=[{id:'calculator',label:'Cost calculator',icon:Calculator},{id:'filaments',label:'Filament library',icon:Layers3},{id:'printers',label:'Printer profiles',icon:Printer},{id:'history',label:'Saved quotes',icon:LayoutDashboard},{id:'products',label:'Products',icon:Package}]
function navigate(id){page.value=id;mobileMenu.value=false;if(tourActive.value){if(tourStep.value===0&&id==='filaments')nextTour();else if(tourStep.value===2&&id==='printers')nextTour();else if(tourStep.value===4&&id==='settings')nextTour();else if(tourStep.value===5&&id==='calculator')finishTour()}}
const pageTitle=computed(()=>nav.find(n=>n.id===page.value)?.label||'Calculator')

// Shared first-run guide: completion is persisted in the server-side SQLite state.
const tourActive=ref(false),tourStep=ref(0)
const tourPosition=ref({top:'90px',left:'300px'})
let tourObserver=null
function positionTour(){
  if(!tourActive.value)return
  const target=document.querySelector(`[data-tour="${tourCurrent.value.target}"]`)
  if(!target)return
  const r=target.getBoundingClientRect(), width=Math.min(390,window.innerWidth-24), height=285, gap=18
  let left=r.right+gap
  if(left+width>window.innerWidth-12)left=r.left-width-gap
  if(left<12)left=Math.max(12,Math.min(window.innerWidth-width-12,r.left))
  let top=r.top
  if(top+height>window.innerHeight-12)top=Math.max(12,window.innerHeight-height-12)
  tourPosition.value={top:`${Math.round(top)}px`,left:`${Math.round(left)}px`}
}
watch([tourActive,tourStep,page,mobileMenu],async()=>{await nextTick();positionTour()},{flush:'post'})

const tourSteps=[
  {title:'Your filament library',body:'Start here. Click Filament library in the sidebar to open your material catalogue.',target:'tour-filaments'},
  {title:'Add your first filament',body:'Click Add filament. Enter its name, material and price per kilogram. You can close the editor whenever you like.',target:'tour-add-filament'},
  {title:'Your printer profiles',body:'Next, click Printer profiles in the sidebar to set up your machine.',target:'tour-printers'},
  {title:'Add your printer',body:'Click Add printer to set its wattage, setup time, finishing time and hourly overhead.',target:'tour-add-printer'},
  {title:'Business settings',body:'Click Settings at the bottom of the sidebar to enter your electricity rate, labour rate and branding.',target:'tour-settings'},
  {title:'Make your first quote',body:'Head back to Cost calculator. Select a filament and printer, enter print time and material used, and see your costs instantly.',target:'tour-calculator'}
]
const tourCurrent=computed(()=>tourSteps[tourStep.value]||tourSteps[0])
function startTour(){editingFilament.value=null;editingPrinter.value=null;page.value='calculator';tourStep.value=0;tourActive.value=true;sidebarCollapsed.value=false;mobileMenu.value=false}
function nextTour(){tourStep.value=Math.min(tourStep.value+1,tourSteps.length-1);editingFilament.value=null;editingPrinter.value=null;sidebarCollapsed.value=false;const destinations=['filaments','filaments','printers','printers','settings','calculator'];page.value=destinations[tourStep.value]}
function finishTour(){tourActive.value=false;state.value.settings.onboardingCompleted=true;toast('You’re all set! Happy printing ✨')}
function skipTour(){finishTour()}

</script>

<template>
<div class="shell" :class="{'dark-mode':isDark,'sidebar-collapsed':sidebarCollapsed,'tour-running':tourActive}" :data-tour-step="tourActive?tourCurrent.target:null" :style="theme">
  <aside class="sidebar" :class="{open:mobileMenu}">
    <div class="brand"><div class="brand-icon"><img v-if="state.settings.logo" :src="state.settings.logo" alt="Site logo"/><Box v-else :size="23" :stroke-width="2.5"/></div><div><strong>{{state.settings.siteTitle||'PrintQuote'}}<span>.</span></strong><small>{{state.settings.siteSubtitle||'PRINT COST STUDIO'}}</small></div></div>
    <button class="sidebar-collapse" type="button" @click="sidebarCollapsed=!sidebarCollapsed" :title="sidebarCollapsed?'Expand sidebar':'Collapse sidebar'" :aria-label="sidebarCollapsed?'Expand sidebar':'Collapse sidebar'"><ChevronRight v-if="sidebarCollapsed" :size="17"/><ChevronLeft v-else :size="17"/></button>
    <nav><button v-for="n in nav" :key="n.id" :title="n.label" :data-tour="'tour-'+n.id" :class="['nav-link',{active:page===n.id}]" @click="navigate(n.id)"><component :is="n.icon" :size="18"/><span>{{n.label}}</span><ChevronRight class="chev" :size="15"/></button></nav>
    <div class="sidebar-footer"><button class="sidebar-settings" data-tour="tour-settings" :class="{active:page==='settings'}" type="button" @click="navigate('settings')" title="Settings"><Settings2 :size="18"/><span>Settings</span></button></div>
  </aside>
  <div v-if="mobileMenu" class="mobile-overlay" @click="mobileMenu=false"></div>
  <main class="main">
    <header class="topbar"><button class="mobile-toggle" type="button" @click="mobileMenu=!mobileMenu" aria-label="Open navigation"><Menu :size="21"/></button><div class="breadcrumb">Workspace <ChevronRight :size="14"/> <b>{{pageTitle}}</b></div><div class="top-right"><button class="tour-replay" type="button" @click="startTour" title="Show the guided tour" aria-label="Show guided tour"><HelpCircle :size="18"/></button><button class="theme-toggle" type="button" @click="cycleTheme" :title="themeLabel" :aria-label="themeLabel"><Monitor v-if="state.settings.themeMode==='auto'" :size="17"/><Sun v-else-if="state.settings.themeMode==='light'" :size="17"/><Moon v-else :size="17"/><span>{{state.settings.themeMode}}</span></button><div class="avatar"><img v-if="state.settings.logo" :src="state.settings.logo" alt="Logo"/><span v-else>{{(state.settings.siteTitle||'PQ').slice(0,2).toUpperCase()}}</span></div></div></header>
    <div class="content"><div v-if="!ready" class="db-warning">Cannot load the shared workspace. Check the application API container and refresh the page. No local changes will be saved until the connection succeeds.</div>
      <div v-if="page==='calculator'">
        <div class="page-head"><div><div class="eyebrow">ESTIMATE & QUOTE</div><h1>Print cost calculator</h1><p>Know your costs. Price every print with confidence.</p></div><button class="btn primary" @click="saveQuote"><Plus :size="17"/> Save quote</button></div>
        <div class="stats-grid">
          <div class="stat"><div class="stat-top"><span>Total production cost</span><div class="mini-icon violet"><PoundSterling :size="17"/></div></div><div class="stat-value">{{money(calc.cost)}}</div><small>All costs included</small></div>
          <div class="stat"><div class="stat-top"><span>Suggested selling price</span><div class="mini-icon blue"><Calculator :size="17"/></div></div><div class="stat-value">{{money(calc.price)}}</div><small>{{calc.margin}}% profit margin</small></div>
          <div class="stat"><div class="stat-top"><span>Estimated profit</span><div class="mini-icon green"><TrendingUp :size="17"/></div></div><div class="stat-value profit">{{money(calc.profit)}}</div><small>{{money(calc.unit)}} per item selling price</small></div>
        </div>
        <div class="two-col">
          <section class="card"><div class="card-heading"><div><h2>Print details</h2><p>Enter your slicer estimates and select materials.</p></div><div class="card-badge">01 / INPUT</div></div>
            <div class="field"><label>Project name <span>Optional</span></label><input v-model="quote.name" placeholder="e.g. Custom phone stand"/></div>
            <div class="field-grid"><div class="field"><label>Printer model</label><select v-model="quote.printerId"><option disabled value="">Select printer</option><option v-for="p in state.printers" :value="p.id" :key="p.id">{{p.name}}</option></select></div><div class="field"><label>Filament</label><select v-model="quote.filamentId"><option disabled value="">Select filament</option><option v-for="f in state.filaments" :value="f.id" :key="f.id">{{f.brand ? f.brand+' · ' : ''}}{{f.name}}</option></select></div></div>
            <div class="field-grid"><div class="field"><label>Filament used <span>grams / item</span></label><div class="input-unit"><input type="number" min="0" step="0.1" v-model.number="quote.grams"/><span>g</span></div></div><div class="field"><label>Quantity</label><div class="input-unit"><input type="number" min="1" step="1" v-model.number="quote.quantity"/><span>pcs</span></div></div></div>
            <div class="field"><label>Print duration <span>per item</span></label><div class="field-grid"><div class="input-unit"><input type="number" min="0" step="1" v-model.number="quote.hours"/><span>hours</span></div><div class="input-unit"><input type="number" min="0" max="59" step="1" v-model.number="quote.minutes"/><span>min</span></div></div></div>
            <div class="field-grid"><div class="field"><label>Target profit margin</label><div class="input-unit"><input type="number" min="0" max="99.9" step="1" v-model.number="quote.margin"/><span>%</span></div></div><div class="field"><label>Extra cost <span>per item</span></label><div class="input-unit"><input type="number" min="0" step="0.01" v-model.number="quote.extraCost"/><span>{{state.settings.currency==='GBP'?'£':state.settings.currency==='USD'?'$':'€'}}</span></div></div></div>
            <div class="info-box"><Info :size="17"/><span>Printer setup, post-processing, power consumption and machine overhead are pulled automatically from your printer profile.</span></div>
          </section>
          <section class="card result-card"><div class="card-heading"><div><h2>Cost breakdown</h2><p>A clear view of where every penny goes.</p></div><div class="card-badge">02 / RESULTS</div></div>
            <div class="breakdown"><div class="cost-row"><div><span class="cost-icon"><Layers3 :size="16"/></span>Filament <small>{{num(quote.grams)*calc.qty}}g total</small></div><strong>{{money(calc.material)}}</strong></div><div class="cost-row"><div><span class="cost-icon"><Zap :size="16"/></span>Electricity <small>{{printer?.power||0}} W</small></div><strong>{{money(calc.energy)}}</strong></div><div class="cost-row"><div><span class="cost-icon"><Clock3 :size="16"/></span>Labour <small>Setup + finishing</small></div><strong>{{money(calc.labour)}}</strong></div><div class="cost-row"><div><span class="cost-icon"><Printer :size="16"/></span>Machine overhead <small>Wear & maintenance</small></div><strong>{{money(calc.overhead)}}</strong></div><div class="cost-row"><div><span class="cost-icon"><Plus :size="16"/></span>Additional costs</div><strong>{{money(calc.extras)}}</strong></div></div>
            <div class="totals"><div><span>Production cost</span><strong>{{money(calc.cost)}}</strong></div><div><span>Profit ({{calc.margin}}% margin)</span><strong class="profit">+ {{money(calc.profit)}}</strong></div></div>
            <div class="grand-total"><div><span>RECOMMENDED SELLING PRICE</span><strong>{{money(calc.price)}}</strong><small>{{money(calc.unit)}} per item · {{calc.qty}} item{{calc.qty===1?'':'s'}}</small></div><TrendingUp :size="29"/></div>
            <p class="footnote">Profit margin = profit ÷ selling price. This differs from markup, which is profit ÷ cost. Prices exclude VAT and payment/platform fees unless added as extra costs.</p>
          </section>
        </div>
      </div>
      <div v-if="page==='filaments'"><div class="page-head"><div><div class="eyebrow">MATERIALS</div><h1>Filament library</h1><p>Keep your materials, cost per kilogram and supplier links in one place.</p></div><button class="btn primary" data-tour="tour-add-filament" @click="newFilament"><Plus :size="17"/> Add filament</button></div><div class="table-card"><div class="table-wrap"><table><thead><tr><th>FILAMENT</th><th>MATERIAL</th><th>COLOUR</th><th>PRICE / KG</th><th>SUPPLIER</th><th></th></tr></thead><tbody><tr v-for="f in state.filaments" :key="f.id"><td><strong>{{f.name}}</strong><small>{{f.brand||'Unbranded'}}</small></td><td><span class="tag">{{f.material}}</span></td><td>{{f.colour||'—'}}</td><td class="bold">{{money(f.price)}}</td><td><a v-if="f.url" :href="f.url" target="_blank" rel="noopener noreferrer" class="link">Buy filament <ExternalLink :size="13"/></a><span v-else class="muted">Not set</span></td><td class="actions"><button class="btn small" @click="editFilament(f)">Edit</button><button class="icon-button danger" title="Delete" @click="removeFilament(f.id)"><Trash2 :size="16"/></button></td></tr><tr v-if="!state.filaments.length"><td colspan="6" class="empty">No filaments yet. Add your first material to get started.</td></tr></tbody></table></div></div><div class="info-box page-info"><Info :size="17"/>This is a pricing library, not inventory tracking. Filament quantities and stock levels are intentionally not tracked.</div></div>
      <div v-if="page==='printers'"><div class="page-head"><div><div class="eyebrow">EQUIPMENT</div><h1>Printer profiles</h1><p>Configure a cost profile for every printer model you use.</p></div><button class="btn primary" data-tour="tour-add-printer" @click="newPrinter"><Plus :size="17"/> Add printer</button></div><div class="printer-grid"><div v-for="p in state.printers" :key="p.id" class="card printer-card"><div class="printer-top"><div class="printer-illustration"><Printer :size="27"/></div><span class="tag">{{p.technology}}</span></div><h2>{{p.name}}</h2><div class="printer-details"><div><span>Average power</span><strong>{{p.power}} W</strong></div><div><span>Setup time / job</span><strong>{{p.setupMinutes}} min</strong></div><div><span>Post-processing / item</span><strong>{{p.postMinutes}} min</strong></div><div><span>Machine overhead / hr</span><strong>{{money(p.overheadRate)}}</strong></div></div><div class="printer-actions"><button class="btn small" @click="editPrinter(p)">Edit profile</button><button class="icon-button danger" @click="removePrinter(p.id)"><Trash2 :size="16"/></button></div></div><button class="add-card" @click="newPrinter"><Plus :size="26"/><strong>Add printer profile</strong><span>Set up another machine</span></button></div></div>
      <div v-if="page==='history'"><div class="page-head"><div><div class="eyebrow">YOUR PROJECTS</div><h1>Saved quotes</h1><p>Review past estimates and reuse them for your next print.</p></div></div><div class="table-card"><div class="table-wrap"><table><thead><tr><th>PROJECT</th><th>DATE</th><th>PRINTER</th><th>PRODUCTION COST</th><th>SELLING PRICE</th><th>PROFIT</th><th></th></tr></thead><tbody><tr v-for="q in state.quotes" :key="q.id"><td><strong>{{q.name}}</strong><small>{{q.filament}}</small></td><td>{{new Date(q.date).toLocaleDateString('en-GB')}}</td><td>{{q.printer}}</td><td>{{money(q.result.cost)}}</td><td class="bold">{{money(q.result.price)}}</td><td class="profit bold">{{money(q.result.profit)}}</td><td class="actions"><button class="btn small" @click="loadQuote(q)">Load</button><button class="btn small" @click="productFromQuote(q)">Make product</button><button class="icon-button danger" @click="removeQuote(q.id)"><Trash2 :size="16"/></button></td></tr><tr v-if="!state.quotes.length"><td colspan="7" class="empty">No saved quotes yet. Create an estimate and click “Save quote”.</td></tr></tbody></table></div></div></div>
      <div v-if="page==='products'">
  <div class="page-head"><div><div class="eyebrow">YOUR CATALOGUE</div><h1>Products</h1><p>Keep finished designs and repeat orders separate from one-off quotes.</p></div><button class="btn primary" @click="newProduct"><Plus :size="17"/> Add product</button></div>
  <div class="product-grid"><article v-for="item in state.products" :key="item.id" class="card product-card"><div class="product-top"><div class="product-icon"><Package :size="22"/></div><span class="product-status">{{item.status||'Active'}}</span></div><h2>{{item.name}}</h2><p class="product-description">{{item.description||'No description yet'}}</p><div class="product-meta"><span v-if="item.customer">For {{item.customer}}</span><span v-if="item.sku">{{item.sku}}</span><span>{{state.filaments.find(f=>f.id===item.filamentId)?.name||'Filament not selected'}}</span><span>{{state.printers.find(p=>p.id===item.printerId)?.name||'Printer not selected'}}</span></div><div class="product-price"><small>Saved selling price</small><strong>{{money(item.price)}}</strong></div><div class="product-actions"><button class="btn small" @click="loadProduct(item)">Use in calculator</button><button class="btn small" @click="editingProduct=clone(item)">Edit</button><button class="icon-button danger" aria-label="Delete product" @click="removeProduct(item.id)"><Trash2 :size="16"/></button></div></article>
  <button class="add-card product-add" @click="newProduct"><Plus :size="28"/><strong>Add your first product</strong><span>Save a reusable design or client job</span></button></div>
</div>
<div v-if="page==='settings'"><div class="page-head"><div><div class="eyebrow">PREFERENCES</div><h1>Settings</h1><p>Set the rates used across all your cost estimates.</p></div></div><section class="card branding-panel"><div class="card-heading"><div><h2>Appearance & branding</h2><p>Personalise the entire workspace. Changes appear instantly.</p></div><Settings2 :size="21" class="muted"/></div><div class="branding-grid"><div><div class="field"><label>Site title</label><input v-model="state.settings.siteTitle" maxlength="36" placeholder="PrintQuote"/></div><div class="field"><label>Subtitle / tagline</label><input v-model="state.settings.siteSubtitle" maxlength="50" placeholder="PRINT COST STUDIO"/></div><div class="field"><label>Logo image</label><div class="logo-picker"><div class="logo-preview"><img v-if="state.settings.logo" :src="state.settings.logo" alt="Logo preview"/><Box v-else :size="25"/></div><div><button class="btn small" @click="logoInput?.click()"><Upload :size="15"/> Upload logo</button><button v-if="state.settings.logo" class="btn small" @click="state.settings.logo=''">Remove</button><p class="hint">PNG, JPG, SVG or WebP · max 1 MB</p></div><input ref="logoInput" type="file" accept="image/*" hidden @change="uploadLogo"/></div></div></div><div><div class="field"><label>Accent colour</label><div class="colour-field"><input type="color" v-model="state.settings.accent"/><input v-model="state.settings.accent" aria-label="Accent colour hex" maxlength="7"/></div></div><div class="field"><label>Theme preference</label><select v-model="state.settings.themeMode"><option value="auto">Automatic (system)</option><option value="light">Light</option><option value="dark">Dark</option></select></div><div class="field"><label>Dark canvas colour</label><div class="colour-field"><input type="color" v-model="state.settings.darkBackground"/><input v-model="state.settings.darkBackground" maxlength="7"/></div></div><div class="field"><label>Light canvas colour</label><div class="colour-field"><input type="color" v-model="state.settings.background"/><input v-model="state.settings.background" aria-label="Background colour hex" maxlength="7"/></div></div><p class="appearance-note">A soft, layered canvas keeps your workspace calm and readable in both light and dark mode.</p><button class="btn small" @click="Object.assign(state.settings,{accent:'#6478f5',background:'#f7f8fb',darkBackground:'#11141c',themeMode:'auto'})">Reset colours</button></div></div></section><div class="settings-layout"><section class="card"><div class="card-heading"><div><h2>Business rates</h2><p>Changes are saved automatically.</p></div><Settings2 :size="21" class="muted"/></div><div class="field"><label>Currency</label><select v-model="state.settings.currency"><option value="GBP">British Pound (£)</option><option value="EUR">Euro (€)</option><option value="USD">US Dollar ($)</option></select></div><div class="field"><label>Electricity price <span>per kWh</span></label><div class="input-unit"><input type="number" min="0" step="0.001" v-model.number="state.settings.energyRate"/><span>/ kWh</span></div></div><div class="field"><label>Labour rate <span>per hour</span></label><div class="input-unit"><input type="number" min="0" step="0.5" v-model.number="state.settings.labourRate"/><span>/ hr</span></div></div><div class="field"><label>Default margin <span>for new estimates</span></label><div class="input-unit"><input type="number" min="0" max="99.9" step="1" v-model.number="state.settings.defaultMargin" @change="quote.margin=state.settings.defaultMargin"/><span>%</span></div></div><div class="info-box"><Info :size="17"/>Electricity is calculated from average printer wattage × print duration × your kWh rate. Labour uses the setup and finishing times saved in each printer profile.</div></section><section class="card"><div class="card-heading"><div><h2>Your data</h2><p>Export or restore the shared workspace.</p></div><Download :size="21" class="muted"/></div><p class="secondary-text">Filaments, printers, branding, rates and saved quotes are stored in the built-in SQLite database and shared by every device accessing this server. You can also export a JSON backup.</p><div class="backup-actions"><button class="btn" @click="exportData"><Download :size="16"/> Export backup</button><button class="btn" @click="fileInput?.click()"><Upload :size="16"/> Import backup</button><input ref="fileInput" type="file" accept="application/json,.json" hidden @change="importData"/></div><div class="info-box"><Info :size="17"/>Browser storage is not used for application data. Back up the SQLite database file regularly. This deployment is intended for a trusted private network; add authentication before publishing it online.</div></section></div></div>
      <footer>PrintQuote <span>•</span> Built for makers, designed for clear pricing.</footer>
    </div>
  </main>
  <div v-if="tourActive && ready" class="tour-layer" aria-live="polite">
    <div class="tour-scrim"></div>
    <div class="tour-panel" :style="tourPosition" role="dialog" aria-modal="false" aria-labelledby="tour-title">
      <div class="tour-kicker"><Sparkles :size="16"/> LET'S GET STARTED <span>{{tourStep+1}} / {{tourSteps.length}}</span></div>
      <h2 id="tour-title">{{tourCurrent.title}}</h2><p>{{tourCurrent.body}}</p>
      <div class="tour-progress"><span v-for="(_,i) in tourSteps" :key="i" :class="{filled:i<=tourStep}"></span></div>
      <div class="tour-actions"><button class="btn small" @click="skipTour">Skip tour</button><button class="btn primary small" @click="tourStep===tourSteps.length-1?finishTour():nextTour()">{{tourStep===tourSteps.length-1?'Finish':'Next step'}} <ChevronRight :size="15"/></button></div>
      <small>You can click the highlighted control, or use Next step. Replay this tour anytime with the ? in the header.</small>
    </div>
  </div>
  <div v-if="notification" class="toast"><Check :size="17"/>{{notification}}</div>
  <div v-if="editingProduct" class="modal-backdrop" @click.self="editingProduct=null"><form class="modal" @submit.prevent="saveProduct"><div class="modal-head"><div><h2>Saved product</h2><p>Reusable design or client print</p></div><button type="button" class="icon-button" @click="editingProduct=null"><X :size="20"/></button></div><div class="field-grid"><div class="field"><label>Product name *</label><input required v-model="editingProduct.name" placeholder="e.g. Custom phone stand"/></div><div class="field"><label>SKU / reference</label><input v-model="editingProduct.sku" placeholder="Optional"/></div></div><div class="field"><label>Description</label><input v-model="editingProduct.description" placeholder="What is this product?"/></div><div class="field-grid"><div class="field"><label>Customer (optional)</label><input v-model="editingProduct.customer" placeholder="Client name"/></div><div class="field"><label>Status</label><select v-model="editingProduct.status"><option>Active</option><option>Archived</option><option>Prototype</option></select></div></div><div class="field-grid"><div class="field"><label>Filament</label><select v-model="editingProduct.filamentId"><option value="">Not selected</option><option v-for="f in state.filaments" :key="f.id" :value="f.id">{{f.name}}</option></select></div><div class="field"><label>Printer</label><select v-model="editingProduct.printerId"><option value="">Not selected</option><option v-for="p in state.printers" :key="p.id" :value="p.id">{{p.name}}</option></select></div></div><div class="field-grid"><div class="field"><label>Filament (g)</label><input type="number" min="0" step="0.1" v-model.number="editingProduct.grams"/></div><div class="field"><label>Saved selling price</label><input type="number" min="0" step="0.01" v-model.number="editingProduct.price"/></div></div><div class="field-grid"><div class="field"><label>Print hours</label><input type="number" min="0" step="1" v-model.number="editingProduct.hours"/></div><div class="field"><label>Print minutes</label><input type="number" min="0" step="1" v-model.number="editingProduct.minutes"/></div></div><div class="field"><label>Notes</label><input v-model="editingProduct.notes" placeholder="Finishing or production notes"/></div><div class="modal-actions"><button type="button" class="btn" @click="editingProduct=null">Cancel</button><button type="submit" class="btn primary">Save product</button></div></form></div>
<div v-if="editingFilament" class="modal-backdrop" @click.self="editingFilament=null"><form class="modal" @submit.prevent="saveFilament"><div class="modal-head"><div><h2>{{state.filaments.some(f=>f.id===editingFilament.id)?'Edit filament':'Add filament'}}</h2><p>Material pricing details</p></div><button type="button" class="icon-button" @click="editingFilament=null"><X :size="20"/></button></div><div class="field-grid"><div class="field"><label>Filament name *</label><input v-model="editingFilament.name" required placeholder="e.g. PLA Matte"/></div><div class="field"><label>Brand</label><input v-model="editingFilament.brand" placeholder="e.g. eSUN"/></div></div><div class="field-grid"><div class="field"><label>Material type</label><select v-model="editingFilament.material"><option v-for="m in ['PLA','PLA+','PETG','ABS','ASA','TPU','Nylon','PC','Other']" :key="m">{{m}}</option></select></div><div class="field"><label>Colour / variant</label><input v-model="editingFilament.colour" placeholder="e.g. Matte black"/></div></div><div class="field"><label>Price per kilogram</label><input type="number" min="0" step="0.01" v-model.number="editingFilament.price"/></div><div class="field"><label>Purchase link</label><input type="url" v-model="editingFilament.url" placeholder="https://..."/></div><div class="modal-actions"><button type="button" class="btn" @click="editingFilament=null">Cancel</button><button class="btn primary" type="submit">Save filament</button></div></form></div>
  <div v-if="editingPrinter" class="modal-backdrop" @click.self="editingPrinter=null"><form class="modal" @submit.prevent="savePrinter"><div class="modal-head"><div><h2>{{state.printers.some(p=>p.id===editingPrinter.id)?'Edit printer':'Add printer'}}</h2><p>Printer-specific cost profile</p></div><button type="button" class="icon-button" @click="editingPrinter=null"><X :size="20"/></button></div><div class="field"><label>Printer model *</label><input v-model="editingPrinter.name" required placeholder="e.g. Bambu Lab P1S"/></div><div class="field-grid"><div class="field"><label>Technology</label><select v-model="editingPrinter.technology"><option>FDM</option><option>Resin</option><option>Other</option></select></div><div class="field"><label>Average power consumption (W)</label><input type="number" min="0" step="1" v-model.number="editingPrinter.power"/></div></div><div class="field-grid"><div class="field"><label>Setup time / job (min)</label><input type="number" min="0" step="1" v-model.number="editingPrinter.setupMinutes"/></div><div class="field"><label>Post-processing / item (min)</label><input type="number" min="0" step="1" v-model.number="editingPrinter.postMinutes"/></div></div><div class="field"><label>Machine overhead / print hour</label><input type="number" min="0" step="0.01" v-model.number="editingPrinter.overheadRate"/></div><div class="info-box"><Info :size="17"/>Machine overhead can account for wear, depreciation, servicing and consumables. Enter your own hourly estimate.</div><div class="modal-actions"><button type="button" class="btn" @click="editingPrinter=null">Cancel</button><button class="btn primary" type="submit">Save printer</button></div></form></div>
</div>
</template>
